import "server-only";
import { cacheLife, cacheTag } from "next/cache";
import type { Prisma } from "@prisma/client";
import { db } from "./db";
import { TAGS } from "./tags";

// Storefront-safe projection: never expose costPrice or internal fields.
const cardSelect = {
  id: true,
  name: true,
  slug: true,
  brand: true,
  material: true,
  price: true,
  mrp: true,
  stock: true,
  ratingAvg: true,
  ratingCount: true,
  emiEligible: true,
  engravingAvailable: true,
  isFeatured: true,
  category: { select: { name: true, slug: true } },
  images: { select: { url: true, alt: true }, orderBy: { sortOrder: "asc" }, take: 2 },
} satisfies Prisma.ProductSelect;

export type ProductCard = Prisma.ProductGetPayload<{ select: typeof cardSelect }>;

export async function getCategories() {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.categories, TAGS.products);
  return db.category.findMany({
    where: { isActive: true },
    orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    include: { _count: { select: { products: { where: { isActive: true } } } } },
  });
}

export async function getCategoryBySlug(slug: string) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.categories);
  return db.category.findFirst({
    where: { slug, isActive: true },
    include: { children: { where: { isActive: true }, orderBy: { sortOrder: "asc" } }, parent: true },
  });
}

export async function getFeaturedProducts(limit = 8) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.products);
  return db.product.findMany({
    where: { isActive: true, isFeatured: true },
    select: cardSelect,
    orderBy: { updatedAt: "desc" },
    take: limit,
  });
}

export async function getNewArrivals(limit = 8) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.products);
  return db.product.findMany({ where: { isActive: true }, select: cardSelect, orderBy: { createdAt: "desc" }, take: limit });
}

export async function getBestSellers(limit = 8) {
  "use cache";
  cacheLife("hours");
  cacheTag(TAGS.products);
  const top = await db.orderItem.groupBy({
    by: ["productId"],
    where: { productId: { not: null }, order: { paidAt: { not: null } } },
    _sum: { quantity: true },
    orderBy: { _sum: { quantity: "desc" } },
    take: limit,
  });
  const ids = top.map((t) => t.productId!);
  const products = await db.product.findMany({ where: { id: { in: ids }, isActive: true }, select: cardSelect });
  const sorted = ids.map((id) => products.find((p) => p.id === id)).filter((p): p is ProductCard => Boolean(p));
  if (sorted.length >= 4) return sorted;
  return db.product.findMany({ where: { isActive: true }, select: cardSelect, orderBy: { ratingCount: "desc" }, take: limit });
}

export type ProductQuery = {
  q?: string;
  category?: string;
  material?: string;
  min?: number;
  max?: number;
  inStock?: boolean;
  emi?: boolean;
  sort?: "relevance" | "price-asc" | "price-desc" | "newest" | "rating" | "discount";
  page?: number;
};

export const PAGE_SIZE = 24;

export async function searchProducts(query: ProductQuery) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.products);

  const where: Prisma.ProductWhereInput = { isActive: true };
  if (query.q) {
    const terms = query.q.split(/\s+/).filter(Boolean).slice(0, 6);
    where.AND = terms.map((t) => ({
      OR: [
        { name: { contains: t, mode: "insensitive" } },
        { brand: { contains: t, mode: "insensitive" } },
        { material: { contains: t, mode: "insensitive" } },
        { sku: { contains: t, mode: "insensitive" } },
        { tags: { has: t.toLowerCase() } },
        { category: { name: { contains: t, mode: "insensitive" } } },
      ],
    }));
  }
  if (query.category) {
    where.category = { OR: [{ slug: query.category }, { parent: { slug: query.category } }] };
  }
  if (query.material) where.material = { equals: query.material, mode: "insensitive" };
  if (query.min || query.max) where.price = { ...(query.min ? { gte: query.min } : {}), ...(query.max ? { lte: query.max } : {}) };
  if (query.inStock) where.stock = { gt: 0 };
  if (query.emi) where.emiEligible = true;

  const orderBy: Prisma.ProductOrderByWithRelationInput[] =
    query.sort === "price-asc" ? [{ price: "asc" }]
    : query.sort === "price-desc" ? [{ price: "desc" }]
    : query.sort === "newest" ? [{ createdAt: "desc" }]
    : query.sort === "rating" ? [{ ratingAvg: "desc" }, { ratingCount: "desc" }]
    : [{ isFeatured: "desc" }, { ratingCount: "desc" }, { createdAt: "desc" }];

  const page = Math.max(1, query.page ?? 1);
  const [items, total, materials] = await Promise.all([
    db.product.findMany({ where, select: cardSelect, orderBy, skip: (page - 1) * PAGE_SIZE, take: PAGE_SIZE }),
    db.product.count({ where }),
    db.product.findMany({ where: { isActive: true, material: { not: null } }, select: { material: true }, distinct: ["material"] }),
  ]);
  if (query.sort === "discount") items.sort((a, b) => (b.mrp - b.price) / b.mrp - (a.mrp - a.price) / a.mrp);
  return { items, total, page, pages: Math.max(1, Math.ceil(total / PAGE_SIZE)), materials: materials.map((m) => m.material!).sort() };
}

export async function getProductBySlug(slug: string) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.products, TAGS.product(slug));
  return db.product.findFirst({
    where: { slug, isActive: true },
    select: {
      ...cardSelect,
      sku: true,
      shortDescription: true,
      description: true,
      specs: true,
      tags: true,
      gstRate: true,
      hsnCode: true,
      warranty: true,
      weightGrams: true,
      categoryId: true,
      category: { select: { id: true, name: true, slug: true, parent: { select: { name: true, slug: true } } } },
      images: { select: { url: true, alt: true }, orderBy: { sortOrder: "asc" } },
    },
  });
}

export async function getRelatedProducts(categoryId: string, excludeId: string) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.products);
  return db.product.findMany({
    where: { categoryId, isActive: true, id: { not: excludeId } },
    select: cardSelect,
    orderBy: { ratingCount: "desc" },
    take: 8,
  });
}

export async function getProductReviews(productId: string) {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.reviews(productId));
  const [reviews, dist] = await Promise.all([
    db.review.findMany({
      where: { productId, isApproved: true },
      select: { id: true, rating: true, title: true, body: true, verifiedPurchase: true, createdAt: true, user: { select: { name: true } } },
      orderBy: { createdAt: "desc" },
      take: 20,
    }),
    db.review.groupBy({ by: ["rating"], where: { productId, isApproved: true }, _count: true }),
  ]);
  const distribution = [5, 4, 3, 2, 1].map((r) => ({ rating: r, count: dist.find((d) => d.rating === r)?._count ?? 0 }));
  return { reviews: reviews.map((r) => ({ ...r, user: { name: r.user.name.split(" ")[0] } })), distribution };
}

export async function getBanners() {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.banners);
  return db.banner.findMany({ where: { isActive: true }, orderBy: { sortOrder: "asc" } });
}

export async function getGallery(category?: "ENGRAVING" | "B2B_PROJECT" | "STORE") {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.gallery);
  return db.galleryItem.findMany({
    where: { isPublished: true, ...(category ? { category } : {}) },
    orderBy: [{ sortOrder: "asc" }, { createdAt: "desc" }],
  });
}

export async function getSettings() {
  "use cache";
  cacheLife("max");
  cacheTag(TAGS.settings);
  const rows = await db.siteSetting.findMany();
  return Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
}

/** Typeahead suggestions for the header search box. */
export async function suggestProducts(q: string) {
  "use cache";
  cacheLife("hours");
  cacheTag(TAGS.products, TAGS.categories);
  const term = q.trim().slice(0, 60);
  if (term.length < 2) return { products: [], categories: [] };
  const [products, categories] = await Promise.all([
    db.product.findMany({
      where: {
        isActive: true,
        OR: [
          { name: { contains: term, mode: "insensitive" } },
          { material: { contains: term, mode: "insensitive" } },
          { tags: { has: term.toLowerCase() } },
        ],
      },
      select: { id: true, name: true, slug: true, price: true, images: { select: { url: true }, orderBy: { sortOrder: "asc" }, take: 1 } },
      orderBy: [{ isFeatured: "desc" }, { ratingCount: "desc" }],
      take: 6,
    }),
    db.category.findMany({ where: { isActive: true, name: { contains: term, mode: "insensitive" } }, select: { name: true, slug: true }, take: 3 }),
  ]);
  return {
    products: products.map((p) => ({ name: p.name, slug: p.slug, price: p.price, image: p.images[0]?.url ?? null })),
    categories,
  };
}
